import{_ as t,c as a,al as o,o as i}from"./chunks/framework.DCERqlYr.js";const d=JSON.parse('{"title":"Тест MC_02 - Повна автономність","description":"","frontmatter":{},"headers":[],"relativePath":"uk/test_cards/mc_02_full_autonomous.md","filePath":"uk/test_cards/mc_02_full_autonomous.md"}'),r={name:"uk/test_cards/mc_02_full_autonomous.md"};function n(s,e,l,p,u,h){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="тест-mc-02-повна-автономність" tabindex="-1">Тест MC_02 - Повна автономність <a class="header-anchor" href="#тест-mc-02-повна-автономність" aria-label="Permalink to &quot;Тест MC_02 - Повна автономність&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>To test the auto modes such as Mission, RTL, etc...</p><h2 id="preflight" tabindex="-1">Preflight <a class="header-anchor" href="#preflight" aria-label="Permalink to &quot;Preflight&quot;">​</a></h2><p>Plan a mission on the ground. Ensure the mission has</p><ul><li>Takeoff as first waypoint</li><li>Changes in Altitude throughout the mission</li><li>Last waypoint is an RTL</li><li>Duration of 5 to 6 minutes</li></ul><h2 id="flight-tests" tabindex="-1">Flight Tests <a class="header-anchor" href="#flight-tests" aria-label="Permalink to &quot;Flight Tests&quot;">​</a></h2><p>❏ Mission</p><p>    ❏ Auto take-off</p><p>    ❏ Changes in Altitude throughout the mission</p><p>    ❏ First waypoint set to Takeoff</p><p>    ❏ Enable Mission End RTL</p><p>    ❏ Duration of 5 to 6 minutes</p><p>    ❏ Auto Disarm on land</p><p>❏ Mission + Manual arm</p><p>    ❏ Arm in any manual mode</p><p>    ❏ Engage Auto (Mission Mode) to trigger take-off</p><p>    ❏ Observe tracking, cornering and proper RTL performance</p><p>    ❏ Upon touching ground, copter should disarm automatically within 2 seconds (disarm time set by parameter: <a href="./../advanced_config/parameter_reference.html#COM_DISARM_LAND">COM_DISARM_LAND</a>)</p><p>❏ RTL</p><p>    ❏ Arm and takeoff in position mode</p><p>    ❏ Fly out ~10m from start point</p><p>    ❏ Engage RTL Mode</p><p>    ❏ Observe tracking, cornering and proper RTL performance</p><h2 id="очікувані-результати" tabindex="-1">Очікувані результати <a class="header-anchor" href="#очікувані-результати" aria-label="Permalink to &quot;Очікувані результати&quot;">​</a></h2><ul><li>Зліт повинен бути плавним, коли газ піднято</li><li>Місія має бути завантажена при першій спробі</li><li>Дрон повинен автоматично злетіти після ввімкнення автоматичного режиму</li><li>Vehicle shoud adjust height to RTL altitude before returning home</li><li>Після посадки, коптер не повинен підскакувати на землі</li></ul>',26)]))}const m=t(r,[["render",n]]);export{d as __pageData,m as default};
